function youtubeVideo(raw) {
  const url = typeof raw === "string" ? raw.trim() : "";
  if (url.length > 500 || /\s/.test(url)) throw new Error("Supply one full YouTube video URL");
  const short = url.match(/^https:\/\/youtu\.be\/([A-Za-z0-9_-]{11})(?:[?#].*)?$/i);
  const path = url.match(
    /^https:\/\/(?:www\.|m\.)?youtube\.com\/(?:shorts|live)\/([A-Za-z0-9_-]{11})(?:[?#].*)?$/i,
  );
  const watch = url.match(/^https:\/\/(?:www\.|m\.)?youtube\.com\/watch\?([^#]*)/i);
  const values =
    watch?.[1]
      .split("&")
      .filter((part) => part.startsWith("v="))
      .map((part) => part.slice(2)) ?? [];
  const id = short?.[1] ?? path?.[1] ?? (values.length === 1 ? values[0] : "");
  if (!/^[A-Za-z0-9_-]{11}$/.test(id)) throw new Error("Supply one full YouTube video URL");
  return id;
}
export default ({ body }) => {
  const videoId = youtubeVideo(body.url);
  return {
    videoId,
    state: { phase: "list", videoId },
    metadata: { query: { video_id: videoId, language_code: "en-US", need_format: false } },
  };
};

