function buildCaptionRequest(state) {
  const root = "/api/v1/youtube/web_v2/";
  const query =
    state.phase === "poll"
      ? { job_id: state.job, format: "txt" }
      : state.phase === "track"
        ? { video_id: state.videoId, language_code: state.language, format: "txt" }
        : { video_id: state.videoId };
  return {
    path: root + (state.phase === "poll" ? "get_video_captions_result" : "get_video_captions"),
    request: { query },
  };
}
export default ({ initial, previous }) => {
  const state = previous ?? initial;
  return { ...buildCaptionRequest(state), state };
};

