function nextCaptionState(state, reply) {
  const payload = reply?.data;
  // Only a track request has a video and language already verified against the caption listing.
  const data =
    state.phase === "track" && typeof payload === "string"
      ? { content: payload, video_id: state.videoId, language_code: state.language, format: "txt" }
      : payload;
  if (reply?.code !== 200 || !data || typeof data !== "object" || Array.isArray(data)) {
    throw new Error("TikHub did not return YouTube captions");
  }
  const languageCode = (value) =>
    typeof value === "string" && /^(?:a\.)?[A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8}){0,3}$/.test(value);
  const requiresVideo =
    state.phase === "list" || (state.phase === "track" && data.status === "processing");
  const mismatchedVideo =
    (requiresVideo || Object.hasOwn(data, "video_id")) && data.video_id !== state.videoId;
  const mismatchedJob = state.phase === "poll" && data.job_id !== state.job;
  if (mismatchedVideo || mismatchedJob) {
    throw new Error("TikHub returned captions for a different video or job");
  }
  if (state.phase !== "poll" && data.status === "processing") {
    if (typeof data.job_id !== "string" || !/^[A-Za-z0-9_-]{8,128}$/.test(data.job_id))
      throw new Error("TikHub did not return a valid caption job");
    return {
      pending: true,
      state: { ...state, phase: "poll", job: data.job_id, pollCount: 0 },
      transcript: "",
      language: "",
    };
  }
  if (state.phase === "list") {
    if (!Array.isArray(data.captions))
      throw new Error("TikHub did not return a caption language list");
    const tracks = data.captions.map((track) => track?.language_code).filter(languageCode);
    if (!tracks.length) throw new Error("The video has no available captions");
    const language =
      tracks.find((code) => code === "en") ??
      tracks.find((code) => /^en-/i.test(code)) ??
      tracks.find((code) => code === "a.en") ??
      tracks[0];
    return {
      pending: true,
      state: { ...state, phase: "track", language },
      transcript: "",
      language: "",
    };
  }
  if (state.phase === "poll" && ["queued", "active"].includes(data.status)) {
    if (state.pollCount + 1 >= 12)
      throw new Error("TikHub caption job did not finish after 12 checks");
    return {
      pending: true,
      state: { ...state, pollCount: state.pollCount + 1 },
      transcript: "",
      language: "",
    };
  }
  if (
    (state.phase === "poll" && data.status !== "completed") ||
    (state.phase === "track" && data.status != null && data.status !== "completed")
  ) {
    throw new Error("TikHub caption processing did not complete");
  }
  const language = Object.hasOwn(data, "language_code")
    ? data.language_code
    : state.phase === "track"
      ? state.language
      : undefined;
  const transcript = typeof data.content === "string" ? data.content.trim() : "";
  const format = Object.hasOwn(data, "format")
    ? data.format
    : state.phase === "track"
      ? "txt"
      : undefined;
  if (
    !languageCode(language) ||
    (state.language && state.language !== language) ||
    format !== "txt" ||
    !transcript ||
    transcript.length > 60000
  )
    throw new Error("TikHub returned missing, mismatched or oversized caption text");
  return { pending: false, state, transcript, language };
}
export default ({ state, reply }) => nextCaptionState(state, reply);

