function videoTitle(reply, id) {
  const current = reply?.data?.playerResponse?.videoDetails;
  if (
    reply?.code !== 200 ||
    current?.videoId !== id ||
    typeof current.title !== "string" ||
    !current.title.trim() ||
    current.title.length > 300
  ) {
    throw new Error("TikHub did not confirm the title of the submitted video");
  }
  return current.title;
}
export default ({ reply, videoId, transcript, language }) => {
  const title = videoTitle(reply, videoId);
  return {
    title,
    input: JSON.stringify({ title, caption_language: language, captions: transcript }),
  };
};

