function summarizeCaptionResult(reply, videoId, title, language) {
  if (reply?.status !== "completed" || !Array.isArray(reply.output))
    throw new Error("OpenAI did not complete the caption summary");
  const messages = reply.output.filter((item) => item.type === "message");
  const message = messages[0];
  if (
    messages.length !== 1 ||
    message.role !== "assistant" ||
    message.status !== "completed" ||
    !Array.isArray(message.content) ||
    message.content.length !== 1 ||
    message.content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return a structured summary");
  }
  const parsed = JSON.parse(message.content[0].text);
  const validText = (text, max) => typeof text === "string" && text.trim() && text.length <= max;
  if (
    !validText(parsed?.summary, 2200) ||
    !Array.isArray(parsed?.key_points) ||
    parsed.key_points.length < 1 ||
    parsed.key_points.length > 6 ||
    !parsed.key_points.every((point) => validText(point, 400))
  ) {
    throw new Error("OpenAI returned an invalid caption summary");
  }
  return {
    videoId,
    videoUrl: "https://www.youtube.com/watch?v=" + videoId,
    title,
    captionLanguage: language,
    summary: parsed.summary.trim(),
    keyPoints: parsed.key_points.map((point) => point.trim()),
  };
}
export default ({ reply, videoId, title, language }) => ({
  result: summarizeCaptionResult(reply, videoId, title, language),
});
